class Solution {
public:
    vector<int> pancakeSort(vector<int>& arr) {
        vector<int> result;
        int n = arr.size();
        for (int value = n; value >= 1; value--) {
            int index = 0;
            for (int i = 0; i < n; i++) {
                if (arr[i] == value) {
                    index = i;
                    break;
                }
            }
            if (index == value - 1) continue;
            if (index != 0) {
                reverse(arr.begin(), arr.begin() + index + 1);
                result.push_back(index + 1);
            }
            reverse(arr.begin(), arr.begin() + value);
            result.push_back(value);
        }
        return result;
    }
};
